type GroupNorm struct {
	Groups int
	Eps    float64
	Weight []float32 // [C]
	Bias   []float32 // [C]
}

// ApplyInPlace normalises x and returns it, so a caller can chain without
// allocating a tensor per norm.
func (g *GroupNorm) ApplyInPlace(x *Tensor) (*Tensor, error) {
