			// before the end of that.
			var sum, sumSq float64
			for c := c0; c < c0+perGroup; c++ {
				p := x.Plane(n, c)
				for _, v := range p {
					sum += float64(v)
					sumSq += float64(v) * float64(v)
				}
			}
			count := float64(perGroup * hw)
			mean := sum / count
			variance := sumSq/count - mean*mean
			if variance < 0 {
				variance = 0
			}
			inv := float32(1 / sqrt64(variance+g.Eps))
			fmean := float32(mean)
			for c := c0; c < c0+perGroup; c++ {
				p := x.Plane(n, c)
				w, b := g.Weight[c], g.Bias[c]
				scale := w * inv
				shift := b - fmean*scale
				for i, v := range p {
					p[i] = v*scale + shift
				}
			}
		})
	}
	return x, nil
}

// SiLUInPlace applies x * sigmoid(x).
func SiLUInPlace(x *Tensor) *Tensor {
	parallelFor(x.N*x.C, func(p int) {
		plane := x.Plane(p/x.C, p%x.C)
		for i, v := range plane {
			plane[i] = v / (1 + exp32(-v))
		}
	})
	return x
}

// UpsampleNearest2x doubles H and W by pixel replication, which is what
// diffusers' Upsample2D does before its convolution.
func UpsampleNearest2x(x *Tensor) *Tensor {
	out := NewTensor(x.N, x.C, x.H*2, x.W*2)
	for n := 0; n < x.N; n++ {
		parallelFor(x.C, func(c int) {
			src, dst := x.Plane(n, c), out.Plane(n, c)
			for h := 0; h < x.H; h++ {
				srow := src[h*x.W : (h+1)*x.W]
				for _, dh := range [2]int{h * 2, h*2 + 1} {
					drow := dst[dh*out.W : (dh+1)*out.W]
					for w, v := range srow {
						drow[w*2] = v
						drow[w*2+1] = v
					}
				}
			}
		})
	}
	return out
}

// AddInPlace computes a += b.
func AddInPlace(a, b *Tensor) (*Tensor, error) {
	if a.Len() != b.Len() {
		return nil, fmt.Errorf("vae: cannot add %s to %s", b, a)
	}
	parallelFor(a.N*a.C, func(p int) {
		ap, bp := a.Plane(p/a.C, p%a.C), b.Plane(p/a.C, p%a.C)
		for i := range ap {
			ap[i] += bp[i]
		}
	})
	return a, nil
}
package vae

import "math"

func sqrt64(v float64) float64 { return math.Sqrt(v) }

// exp32 is math.Exp at float32 width. SiLU is evaluated elementwise over
// tens of millions of values, and the float64 conversion is the whole cost,
// but correctness first: this matches PyTorch, which also computes sigmoid
// in the tensor's own precision via a float32 expf.
func exp32(v float32) float32 { return float32(math.Exp(float64(v))) }

