	}
	var m manifest
	if err := json.Unmarshal(buf, &m); err != nil {
		t.Fatal(err)
	}
	return &m
}

// loadRef reads one dumped tensor as NCHW float32.
func loadRef(t *testing.T, m *manifest, name string) *Tensor {
	t.Helper()
	meta, ok := m.Tensors[name]
	if !ok {
