	d := loadTiny(t)
	m := loadManifestFrom(t, tinyRefDir, tinyGen+" --latent-size 16")

	peak, where := 0.0, ""
	old := convTap
	defer func() { convTap = old }()
	convTap = func(c *Conv2D, x *Tensor) {
		if v := absMax(x); v > peak {
			peak, where = v, fmt.Sprintf("conv %d->%d at %dx%d", c.InC, c.OutC, x.H, x.W)
		}
	}
