		{"caption not refined", controls{staleCaption: true}},
		{"caption positions from 0", controls{capPosFromZero: true}},
	} {
		p.ctl = c.ctl
		latents := append([]float32(nil), init...)
		img, _, err := p.GenerateFrom(m.Prompt, latents, nil)
		p.ctl = controls{}
		if err != nil {
			t.Fatalf("%s: %v", c.name, err)
		}
