33	// TestTinyDecoderAgainstDiffusers walks taef1 layer by layer against the
34	// dump. Same argument as TestDecoderAgainstDiffusers: nineteen layers of
35	// convolution compose into an image, and an end-to-end check can only say
36	// that the image is wrong.
37	func TestTinyDecoderAgainstDiffusers(t *testing.T) {
38		d := loadTiny(t)
39		m := loadManifestFrom(t, tinyRefDir, tinyGen+" --latent-size 16")
40	
41		latent := loadRef(t, m, "latent")
42		// The clamp, which diffusers puts in DecoderTiny.forward rather than in
43		// the Sequential, and which is therefore the one piece of this decoder
44		// that no weight name would reveal.
45		h := &Tensor{N: latent.N, C: latent.C, H: latent.H, W: latent.W,
46			Data: make([]float32, latent.Len())}
47		for i, v := range latent.Data {
48			h.Data[i] = tanh32(v/3) * 3
49		}
50		compare(t, "clamped", h, loadRef(t, m, "clamped"))
51	
52		var err error
53		for _, l := range d.Layers {
54			switch {
55			case l.Conv != nil:
56				if h, err = l.Conv.Apply(h); err != nil {
57					t.Fatal(err)
58				}
59			case l.Block != nil:
60				if h, err = l.Block.Apply(h); err != nil {
61					t.Fatal(err)
62				}
63			case l.Upsample:
64				h = UpsampleNearest2x(h)
65			case l.ReLU:
66				ReLUInPlace(h)
67			}
68			compare(t, fmt.Sprintf("layers.%d", l.Index), h, loadRef(t, m, fmt.Sprintf("layers.%d", l.Index)))
69		}
70	}
