72	// TestTinyDecoderEndToEnd runs Apply the way a preview will, so the clamp and
73	// the [0,1] -> [-1,1] tail are covered as well as the layers.
74	func TestTinyDecoderEndToEnd(t *testing.T) {
75		d := loadTiny(t)
